/* ───────────────────────────────────────────────────────────
   24. 过渡动画控制
─────────────────────────────────────────────────────────── */

/* 装饰伪元素禁止动画 */
.mes::before, .mes::after,
.mes_block::before, .mes_block::after,
.mesAvatarWrapper::before, .mesAvatarWrapper::after,
.mes .avatar::before, .mes .avatar::after,
hr::before, hr::after {
    animation: none !important;
}

/* UI元素允许正常过渡 */
#send_textarea {
    transition: none !important;
}
/* ───────────────────────────────────────────────────────────
   25. 加载动画 (#load-spinner)☆云朵心心
─────────────────────────────────────────────────────────── */

/* 隐藏原始齿轮 */
#load-spinner::before,
#load-spinner::after {
    display: none !important;content: none !important;
}

#load-spinner * {
    display: none !important;
}

#load-spinner {
    /* 清除原有样式 */
    border: none !important;
    border-top: none !important;
    background-color: transparent !important;
    background: none !important;
    box-shadow: none !important;

    /* 设置云朵心心图标 */
    width: 80px !important;
    height: 70px !important;
    background-image: url("data:image/svg+xml,%3Csvg viewBox='0 0 40 35' xmlns='http://www.w3.org/2000/svg'%3E%3Ccircle cx='14' cy='12' r='7' fill='%23DDEBF2'/%3E%3Ccircle cx='24' cy='8' r='9' fill='%23DDEBF2'/%3E%3Ccircle cx='32' cy='12' r='6' fill='%23DDEBF2'/%3E%3Crect x='14' y='8' width='18' height='12' rx='5' fill='%23DDEBF2'/%3E%3Cpath d='M12 22 C10 20 8 22 12 26 C16 22 14 20 12 22Z' fill='%23EBB9C0' opacity='0.6'/%3E%3Cpath d='M22 25 C20 23 18 25 22 29 C26 25 24 23 22 25Z' fill='%23819DC5' opacity='0.5'/%3E%3Cpath d='M32 23 C30 21 28 23 32 27 C36 23 34 21 32 23Z' fill='%23EBB9C0' opacity='0.4'/%3E%3C/svg%3E") !important;
    background-size: contain !important;
    background-repeat: no-repeat !important;
    background-position: center !important;

    /* 停掉原来的旋转，换成浮动动画 */
    animation: cloudFloat 1.8s ease-in-out infinite !important;border-radius: 0 !important;
}

/* 云朵上下浮动 + 心心缩放 */
@keyframes cloudFloat {
    0%, 100% {
        transform: translateY(0) scale(1);
        opacity: 0.85;
    }
    50% {
        transform: translateY(-10px) scale(1.08);
        opacity: 1;
    }
}

